def transform(grid):
    """Invert the two-color image, mapping the sparse marker color to zero."""
    colors = {v for row in grid for v in row}
    marker = next((v for v in colors if v != 5), None)
    if marker is None:
        return [row[:] for row in grid]
    return [[0 if v == marker else marker for v in row] for row in grid]

